input.code:
// Combined DSL: workspace.dsl with its !include directives resolved inline,
// matching the content of the individual files in /work.
const dsl = `workspace "Online Store" "An example multi-file Structurizr workspace assembled with !include directives." {

    model {
        // ---- people.dsl ----
        person "Alice" {
            "A customer who shops on the Online Store."
        }

        person "Bob" {
            "A support agent who helps customers with their orders."
        }

        // ---- softwareSystems.dsl ----
        softwareSystem "Online Store" {
            "Allows customers to browse the catalogue and place orders."
        }

        softwareSystemExternal "Payment Provider" {
            "A third-party service that processes card payments."
        }

        // ---- containers.dsl ----
        softwareSystem "Online Store" {
            webApplication "Storefront" {
                "The customer-facing web application for browsing and ordering."
            }
            server "Order Service" {
                "Validates and records customer orders."
            }
            database "Orders Database" {
                "Stores order data."
            }
        }

        // ---- relationships.dsl ----
        "Alice" -> "Storefront" "Places orders through"
        "Bob" -> "Storefront" "Views order status in"
        "Storefront" -> "Order Service" "Submits orders to"
        "Order Service" -> "Orders Database" "Persists orders in"
        "Order Service" -> "Payment Provider" "Charges cards via"
    }

    views {
        // ---- views.dsl ----
        systemContext "Online Store" {
            "Shows the Online Store and the people who interact with it."
            include *
            autoLayout
        }

        container "Online Store" {
            "Shows the containers that make up the Online Store."
            include *
            autoLayout
        }

        styles {
            person {
                background #08427B
                color #FFFFFF
            }
            softwareSystem {
                background #1168BD
                color #FFFFFF
            }
            softwareSystemExternal {
                background #999999
                color #FFFFFF
            }
            container {
                background #438DD5
                color #FFFFFF
            }
        }
    }
}`;

const [validate, parse, inspect] = await Promise.allSettled([
  tools.structurizr.validate({ dsl }),
  tools.structurizr.parse({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);

const unwrap = (r) => (r.status === "fulfilled" ? r.value : { error: r.reason?.message ?? r.reason });
return { validate: unwrap(validate), parse: unwrap(parse), inspect: unwrap(inspect) };

