// Model elements only (people.dsl + softwareSystems.dsl + containers.dsl inlined)
const modelOnly = `workspace "Online Store" "An example multi-file Structurizr workspace assembled with !include directives." {
    model {
        // ---- people.dsl ----
        person "Alice" "A customer who shops on the Online Store."
        person "Bob" "A support agent who helps customers with their orders."
        // ---- softwareSystems.dsl ----
        softwareSystem "Payment Provider" "A third-party service that processes card payments."
        // ---- containers.dsl ----
        softwareSystem "Online Store" "Allows customers to browse the catalogue and place orders." {
            container "Storefront" "The customer-facing web application for browsing and ordering."
            container "Order Service" "Validates and records customer orders."
            container "Orders Database" "Stores order data."
        }
    }
}`;

// Full workspace (adds relationships.dsl + views.dsl)
const full = modelOnly.replace(
  "    }\n}",
  `        // ---- relationships.dsl ----
        "Alice" -> "Storefront" "Places orders through"
        "Bob" -> "Storefront" "Views order status in"
        "Storefront" -> "Order Service" "Submits orders to"
        "Order Service" -> "Orders Database" "Persists orders in"
        "Order Service" -> "Payment Provider" "Charges cards via"
    }

    views {
        // ---- views.dsl ----
        systemContext "Online Store" {
            "Shows the Online Store and the people who interact with it."
            include *
            autoLayout
        }
        container "Online Store" {
            "Shows the containers that make up the Online Store."
            include *
            autoLayout
        }
        styles {
            person { background #08427B color #FFFFFF }
            softwareSystem { background #1168BD color #FFFFFF }
            container { background #438DD5 color #FFFFFF }
        }
    }
}`
);

const [modelValidate, modelParse, modelInspect, fullValidate] = await Promise.allSettled([
  tools.structurizr.validate({ dsl: modelOnly }),
  tools.structurizr.parse({ dsl: modelOnly }),
  tools.structurizr.inspect({ dsl: modelOnly }),
  tools.structurizr.validate({ dsl: full }),
]);
const unwrap = (r) => (r.status === "fulfilled" ? r.value : { error: r.reason?.message ?? String(r.reason) });
return {
  modelValidate: unwrap(modelValidate),
  modelParse: unwrap(modelParse),
  modelInspect: unwrap(modelInspect),
  fullValidate: unwrap(fullValidate),
};

